-- Migration number: 0009 	 2026-11-11T09:00:00.000Z

-- Append-only: earlier migrations are already applied everywhere. This
-- migration adds the listing photo gallery next to the listings model.

-- One row per photo. `storage_key` is generated by the server (a random id plus
-- an extension derived from the validated content type); a caller never supplies
-- it. `position` is the gallery order, kept contiguous from zero by the insert
-- and compact statements, so the first photo is always position 0.
--
-- The content type and byte-size CHECKs mirror the service limits: jpeg, png, or
-- webp only, and at most 1 MiB (1048576 bytes) each. The gallery's insert
-- statement decides the ten-photo cap and the new position together; a CHECK
-- cannot count siblings.
CREATE TABLE listing_photos (
                 id INTEGER PRIMARY KEY AUTOINCREMENT,
         listing_id INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
        storage_key TEXT NOT NULL UNIQUE,
       content_type TEXT NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp')),
          byte_size INTEGER NOT NULL CHECK (byte_size > 0 AND byte_size <= 1048576),
           position INTEGER NOT NULL CHECK (position >= 0),
         created_at INTEGER NOT NULL DEFAULT (CAST(unixepoch('now', 'subsec') * 1000 AS INTEGER))
);

CREATE INDEX idx_listing_photos_listing ON listing_photos(listing_id, position, id);
